// Generates src/generated/* from the manifests (REST endpoints and persisted GraphQL queries).
// Run with `npm run gen`. The manifest is the single source of truth;
// never edit the generated files by hand (CI checks they match the manifest).
import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { z } from 'zod';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const endpointSchema = z.object({
  name: z.string().regex(/^[a-z][a-zA-Z0-9]*$/, 'endpoint name must be camelCase'),
  method: z.enum(['GET', 'POST', 'PUT', 'DELETE']),
  path: z.string().startsWith('/'),
});

const manifestSchema = z.object({
  version: z.number().int().positive(),
  endpoints: z.array(endpointSchema),
});

function loadManifest() {
  const raw = readFileSync(join(root, 'manifest', 'endpoints.json'), 'utf8');
  return manifestSchema.parse(JSON.parse(raw));
}

const persistedQuerySchema = z.object({
  name: z.string().regex(/^[a-z][a-zA-Z0-9]*$/, 'query name must be camelCase'),
  operation: z.string().regex(/^[A-Za-z][A-Za-z0-9]*$/),
  docId: z.string().regex(/^\d+$/),
  pinned: z.boolean().optional(),
  note: z.string().optional(),
});

const persistedManifestSchema = z.object({
  version: z.number().int().positive(),
  appBuild: z.string().regex(/^\d+(\.\d+)+$/),
  queries: z.array(persistedQuerySchema),
});

function loadPersistedQueries() {
  const raw = readFileSync(join(root, 'manifest', 'persisted-queries.json'), 'utf8');
  const manifest = persistedManifestSchema.parse(JSON.parse(raw));
  const names = manifest.queries.map((q) => q.name);
  if (new Set(names).size !== names.length) {
    throw new Error('persisted-queries.json repeats a query name');
  }
  return manifest;
}

function renderPersistedQueries(manifest) {
  const sorted = [...manifest.queries].sort((a, b) => a.name.localeCompare(b.name));
  const entries = sorted
    .map((q) => `  ${q.name}: { operation: '${q.operation}', docId: '${q.docId}' },`)
    .join('\n');
  const names = sorted.map((q) => `'${q.name}'`).join(' | ');
  return `// AUTOGENERATED from manifest/persisted-queries.json. Do not edit by hand.
// Run \`npm run gen\` to regenerate. \`npm run app-build\` updates the manifest from an APK.

export interface PersistedQuery {
  /** The operation name the app sends as its friendly name. */
  readonly operation: string;
  /** The persisted-query id of app build ${manifest.appBuild}. */
  readonly docId: string;
}

/** The name of every persisted query in the manifest. */
export type PersistedQueryName = ${names};

/** Every persisted GraphQL query the SDK sends, by name. */
export const persistedQueries: Record<PersistedQueryName, PersistedQuery> = {
${entries}
};
`;
}

function render(manifest) {
  const sorted = [...manifest.endpoints].sort((a, b) => a.name.localeCompare(b.name));
  const entries = sorted
    .map((e) => `  ${e.name}: { method: '${e.method}', path: '${e.path}' },`)
    .join('\n');
  const names = sorted.map((e) => `'${e.name}'`).join(' | ');
  return `// AUTOGENERATED from manifest/endpoints.json. Do not edit by hand.
// Run \`npm run gen\` to regenerate.

/** One REST endpoint of the private API. A path may hold \`{placeholders}\` for ids. */
export interface EndpointDefinition {
  readonly method: 'GET' | 'POST' | 'PUT' | 'DELETE';
  readonly path: string;
}

/** The name of every endpoint in the manifest. */
export type EndpointName = ${names};

/** Every endpoint the SDK calls, by name. */
export const endpoints: Record<EndpointName, EndpointDefinition> = {
${entries}
};
`;
}

function main() {
  const manifest = loadManifest();
  const outDir = join(root, 'src', 'generated');
  mkdirSync(outDir, { recursive: true });
  writeFileSync(join(outDir, 'endpoints.ts'), render(manifest), 'utf8');
  const persisted = loadPersistedQueries();
  writeFileSync(join(outDir, 'persisted-queries.ts'), renderPersistedQueries(persisted), 'utf8');
  process.stdout.write(
    `generated ${String(manifest.endpoints.length)} endpoints and ${String(persisted.queries.length)} persisted queries\n`,
  );
}

main();
